@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=DM+Sans:wght@400;500;600;700&family=Space+Grotesk:wght@400;500;600;700&display=swap');
:root{font-family:'DM Sans',sans-serif;color:#e8eeea;background:#101513;font-synthesis:none;text-rendering:optimizeLegibility;--bg:#101513;--panel:#171d1a;--panel2:#1d2521;--line:#29332e;--muted:#83918a;--green:#b9fa62;--lime:#c0fb70;--orange:#ff7959;--yellow:#f6cb5d}*{box-sizing:border-box}body{margin:0;min-width:320px;min-height:100vh;background:radial-gradient(ellipse at 60% -30%,#273329 0%,transparent 55%),var(--bg)}button{font:inherit;color:inherit;cursor:pointer}#root{min-height:100vh}.app{max-width:1600px;margin:auto;min-height:100vh;display:flex;flex-direction:column;padding:0 28px}.topbar{height:74px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;gap:14px}.brand{display:flex;align-items:center;gap:12px;min-width:245px}.brand-mark{width:37px;height:37px;border:1px solid #72984c;background:#20291e;border-radius:10px;display:grid;place-items:center;color:var(--lime);font-size:21px}.brand-name{font-family:'Space Grotesk';font-weight:700;letter-spacing:.1em;font-size:15px}.brand-sub{font:10px 'DM Mono';color:var(--muted);letter-spacing:.09em;margin-top:3px}.facility-select{background:#1b221e;border:1px solid var(--line);padding:9px 13px;border-radius:8px;font-size:12px;font-weight:600;display:flex;gap:18px;align-items:center}.facility-select span:last-child{color:var(--muted)}.topright{display:flex;align-items:center;gap:22px}.live-status{color:#8e9b94;font:10px 'DM Mono';letter-spacing:.1em;display:flex;align-items:center;gap:8px}.live-status i{width:7px;height:7px;background:var(--green);border-radius:50%;box-shadow:0 0 11px #b9fa62}.avatar{border-radius:50%;width:32px;height:32px;background:#d3d5ba;color:#253126;display:grid;place-items:center;font-size:11px;font-weight:700}.workspace{display:grid;grid-template-columns:224px minmax(0,1fr) 276px;gap:18px;padding:20px 0 18px;flex:1;min-height:700px}.panel{background:var(--panel);border:1px solid var(--line);border-radius:11px}.left-panel{padding:18px 13px;display:flex;flex-direction:column;gap:22px}.section-title{font:10px 'DM Mono';color:#89958e;letter-spacing:.12em;padding:0 9px;margin-bottom:10px}.floor-card{margin:0 3px;padding:11px;background:#202923;border:1px solid #3c493d;border-radius:8px;display:flex;justify-content:space-between;align-items:center;font-size:12px;font-weight:600}.floor-card small{display:block;color:var(--muted);font:10px 'DM Mono';margin-top:5px}.floor-tag{color:var(--lime);font:10px 'DM Mono'}.tool{border:0;background:transparent;width:100%;display:flex;align-items:center;gap:12px;padding:10px 11px;border-radius:7px;color:#a8b2ac;font-size:12px;text-align:left}.tool:hover{background:#222a25}.tool.active{background:#293421;color:var(--lime);box-shadow:inset 2px 0 var(--lime)}.tool-icon{width:19px;text-align:center;font-size:15px}.tool-count{margin-left:auto;color:#68756d;font:10px 'DM Mono'}.tool-help{margin-top:auto;border-top:1px solid var(--line);padding:13px 8px 0;color:#7e8982;font-size:10px;line-height:1.75}.tool-help b{color:#aab4ae;font-weight:500}.center-col{display:flex;flex-direction:column;gap:14px;min-width:0}.page-head{display:flex;align-items:flex-start;justify-content:space-between}.eyebrow{font:10px 'DM Mono';color:var(--lime);letter-spacing:.14em}.page-head h1{font:600 24px 'Space Grotesk';letter-spacing:-.04em;margin:5px 0 4px}.page-head p{margin:0;color:#8c9891;font-size:12px}.actions{display:flex;gap:8px}.button{border:1px solid #354039;background:#1a211d;border-radius:7px;padding:9px 12px;font-size:11px;font-weight:600}.button:hover{border-color:#61734d}.button.primary{background:var(--lime);border-color:var(--lime);color:#182114}.button.danger{color:#ff997e;border-color:#613d33}.canvas-card{overflow:hidden;position:relative;flex:1;min-height:420px;background:#171e1a;border:1px solid var(--line);border-radius:10px}.canvas-head{height:43px;position:absolute;z-index:2;top:0;left:0;right:0;display:flex;align-items:center;justify-content:space-between;padding:0 15px;background:linear-gradient(#171e1af2,#171e1acc);border-bottom:1px solid #29332e}.canvas-title{font:10px 'DM Mono';letter-spacing:.09em;color:#a4afa8}.canvas-actions{display:flex;align-items:center;gap:8px}.mini-btn{border:1px solid #364139;background:#1b231e;border-radius:5px;padding:5px 8px;font:10px 'DM Mono';color:#a9b5ad}.mini-btn.on{color:var(--lime);border-color:#63774b}.map-wrap{position:absolute;inset:43px 0 0}.map-wrap canvas{width:100%;height:100%;display:block;touch-action:none;cursor:crosshair}.map-label{position:absolute;bottom:14px;left:15px;color:#728078;font:9px 'DM Mono';pointer-events:none}.map-legend{position:absolute;bottom:12px;right:14px;display:flex;gap:12px;pointer-events:none;background:#111713d9;padding:7px 9px;border:1px solid #29332e;border-radius:5px;font:9px 'DM Mono';color:#9ba79f}.legend-dot{width:7px;height:7px;display:inline-block;border-radius:50%;margin-right:5px}.toast{position:absolute;top:55px;left:50%;transform:translateX(-50%);background:#263122;border:1px solid #576e43;color:#d9f9b9;padding:8px 12px;border-radius:6px;font-size:11px;opacity:0;transition:.2s;pointer-events:none;z-index:5;white-space:nowrap}.toast.show{opacity:1}.bottom-stats{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.stat{padding:11px 13px;background:var(--panel);border:1px solid var(--line);border-radius:8px}.stat-label{color:#87938c;font:9px 'DM Mono';letter-spacing:.08em}.stat-value{font:600 18px 'Space Grotesk';margin-top:5px}.stat-value small{font-size:10px;color:#8d9a92;font-weight:400}.right-panel{padding:18px 15px;display:flex;flex-direction:column;gap:20px}.right-panel .section-title{padding:0;margin-bottom:12px}.score-card{background:#20281f;border:1px solid #364534;border-radius:8px;padding:14px}.score-top{display:flex;justify-content:space-between;align-items:center}.score-top span:first-child{font:10px 'DM Mono';letter-spacing:.08em;color:#bac4bc}.score-num{font:600 24px 'Space Grotesk';color:var(--lime)}.score-num small{font-size:11px;color:#9eaa9f}.score-bar{height:5px;background:#364039;border-radius:4px;margin:10px 0}.score-bar div{height:100%;background:var(--lime);border-radius:4px;transition:width .3s}.score-caption{font-size:10px;color:#87938b}.object-list{display:flex;flex-direction:column;gap:7px}.object-row{display:flex;align-items:center;gap:10px;padding:9px;border:1px solid #29332e;border-radius:7px;background:#1a211d}.obj-icon{width:29px;height:29px;border-radius:6px;display:grid;place-items:center;background:#2c3829;color:var(--lime);font-size:14px}.obj-icon.fire{background:#3a2925;color:#ff9870}.obj-name{font-size:11px;font-weight:600}.obj-meta{font:9px 'DM Mono';color:#849088;margin-top:3px}.obj-state{margin-left:auto;width:6px;height:6px;border-radius:50%;background:var(--lime)}.property{border-top:1px solid var(--line);padding-top:16px}.prop-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.prop-label{font:9px 'DM Mono';color:#849088;letter-spacing:.04em}.prop-val{font-size:11px;margin-top:5px}.compliance-row{display:flex;align-items:center;justify-content:space-between;margin:9px 0;font-size:10px;color:#a8b2aa}.pill{padding:4px 7px;border-radius:4px;background:#293627;color:#b9ed88;font:9px 'DM Mono'}.pill.warn{background:#3a3021;color:#f5cf73}.sim-card{margin-top:auto;border:1px solid #3a443b;border-radius:8px;padding:13px;background:#1b221d}.sim-head{display:flex;justify-content:space-between;align-items:center}.sim-title{font:10px 'DM Mono';letter-spacing:.08em}.sim-btn{width:100%;margin-top:12px;padding:10px;border:0;border-radius:6px;background:var(--lime);color:#182114;font-size:11px;font-weight:700}.sim-btn.running{background:#482a25;color:#ff9b80}.smallprint{font-size:9px;color:#849087;line-height:1.55;margin-top:9px}.mobile-tools{display:none}.footer{height:34px;border-top:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;color:#69766e;font:9px 'DM Mono';letter-spacing:.05em}.footer span:last-child{color:#9aa69c}
@media(max-width:1100px){.workspace{grid-template-columns:190px minmax(0,1fr)}.right-panel{grid-column:1/-1;display:grid;grid-template-columns:1fr 1fr 1fr;gap:15px}.sim-card{margin-top:0}.left-panel{grid-row:1}.center-col{grid-column:2;grid-row:1}.page-head h1{font-size:21px}}
