import './style.css';

type Tool = 'select'|'extinguisher'|'hazard'|'route'|'erase';
type ExtType = 'A'|'B'|'C'|'K';
type HazardType = 'ELECTRICAL'|'GREASE'|'COMBUSTIBLE';
type Cell = { wall:boolean; furniture:boolean; fire:number; smoke:number; electrified:boolean };
type Point = {x:number;y:number};
type Extinguisher = Point & {id:number;type:ExtType;radius:number};
type Hazard = Point & {id:number;type:HazardType;active:boolean};
type Person = Point & {path:Point[];panic:boolean;warden:boolean};
const COLS=30, ROWS=20, TILE=32;
const grid:Cell[][]=Array.from({length:ROWS},(_,y)=>Array.from({length:COLS},(_,x)=>({wall:x===0||y===0||x===COLS-1||y===ROWS-1||((x===10||x===20)&&y>2&&y<17&&y!==9&&y!==10),furniture:false,fire:0,smoke:0,electrified:false})));
// Furniture, rooms and exit are intentionally laid out as a small training facility.
[[5,5],[6,5],[16,5],[17,5],[24,13],[25,13],[7,14],[8,14]].forEach(([x,y])=>grid[y][x].furniture=true);
const exit:Point={x:28,y:10};
let extinguishers:Extinguisher[]=[{id:1,type:'A',x:7,y:9,radius:45},{id:2,type:'C',x:18,y:8,radius:30},{id:3,type:'A',x:24,y:10,radius:45}];
let hazards:Hazard[]=[{id:1,type:'ELECTRICAL',x:16,y:4,active:true},{id:2,type:'GREASE',x:24,y:15,active:true}];
let people:Person[]=[];let route:Point[]=[{x:4,y:9},{x:8,y:9},{x:9,y:10},{x:15,y:10},{x:19,y:10},{x:22,y:10},{x:28,y:10}];
let tool:Tool='select',selected:Point|null=null,snapping=true,running=false,ticks=0,evacuated=0,casualties=0,damage=0,zoom=1,pan={x:0,y:0},dragging=false,dragStart:Point|null=null,simTimer=0,arrowOffset=0,toastTimer=0;
const root=document.querySelector<HTMLDivElement>('#root')!;
root.innerHTML=`<main class="app"><header class="topbar"><div class="brand"><div class="brand-mark">⌁</div><div><div class="brand-name">FIREWATCH</div><div class="brand-sub">FACILITY OPERATIONS</div></div></div><button class="facility-select"><span>▦　Northstar Manufacturing</span><span>⌄</span></button><div class="topright"><div class="live-status"><i></i><span>FACILITY ONLINE</span></div><div class="avatar">JD</div></div></header><div class="workspace"><aside class="left-panel panel"><div><div class="section-title">FACILITY PLAN</div><div class="floor-card"><div>Ground floor<small>Assembly · 1,840 m²</small></div><span class="floor-tag">ACTIVE</span></div></div><div><div class="section-title">TOOLS</div><button class="tool active" data-tool="select"><span class="tool-icon">⌖</span> Select <span class="tool-count">V</span></button><button class="tool" data-tool="extinguisher"><span class="tool-icon">⊕</span> Extinguisher <span class="tool-count">E</span></button><button class="tool" data-tool="hazard"><span class="tool-icon">⚡</span> Hazard <span class="tool-count">H</span></button><button class="tool" data-tool="route"><span class="tool-icon">↗</span> Evacuation route <span class="tool-count">R</span></button><button class="tool" data-tool="erase"><span class="tool-icon">⌫</span> Erase</button></div><div class="tool-help"><b>⌘ Scroll</b> to zoom · <b>Middle-drag</b> to pan<br><b>Tap / click</b> to place · <b>Esc</b> to cancel route</div></aside><section class="center-col"><div class="page-head"><div><div class="eyebrow">LIFE SAFETY / OVERVIEW</div><h1>Ground floor plan</h1><p>Review your layout, resolve risks, and run a drill.</p></div><div class="actions"><button class="button" id="grid-toggle">▦　Grid on</button><button class="button primary" id="export-btn">↥　Export</button></div></div><div class="canvas-card"><div class="canvas-head"><div class="canvas-title">GROUND FLOOR　/　1 : 100</div><div class="canvas-actions"><button class="mini-btn" id="zoom-out">−</button><button class="mini-btn" id="zoom-label">100%</button><button class="mini-btn" id="zoom-in">+</button></div></div><div class="map-wrap"><canvas id="map"></canvas><div class="toast" id="toast"></div><div class="map-label">30 × 20 GRID　·　1 TILE = 0.5 M</div><div class="map-legend"><span><i class="legend-dot" style="background:#bbfa68"></i>SAFE</span><span><i class="legend-dot" style="background:#ff815e"></i>HAZARD</span><span><i class="legend-dot" style="background:#55d889"></i>EXIT ROUTE</span></div></div></div><div class="bottom-stats"><div class="stat"><div class="stat-label">COMPLIANCE SCORE</div><div class="stat-value" id="stat-score">— <small>/ 100</small></div></div><div class="stat"><div class="stat-label">ACTIVE HAZARDS</div><div class="stat-value" id="stat-hazards">02</div></div><div class="stat"><div class="stat-label">EVACUATED</div><div class="stat-value" id="stat-evac">— <small>people</small></div></div><div class="stat"><div class="stat-label">FACILITY DAMAGE</div><div class="stat-value" id="stat-damage">0<small>%</small></div></div></div></section><aside class="right-panel panel"><section><div class="section-title">SAFETY SCORE</div><div class="score-card"><div class="score-top"><span>OVERALL COMPLIANCE</span><div class="score-num" id="score-num">—<small> / 100</small></div></div><div class="score-bar"><div id="score-bar" style="width:0%"></div></div><div class="score-caption" id="score-caption">Run an audit to calculate score</div></div></section><section><div class="section-title">EQUIPMENT & RISKS <span id="obj-count"></span></div><div class="object-list" id="object-list"></div></section><section class="property"><div class="section-title">INSPECTOR</div><div id="inspector" style="font-size:11px;color:#87938b;line-height:1.6">Select a device or node on the plan to inspect its properties.</div></section><section class="property"><div class="section-title">QUICK CHECKS</div><div class="compliance-row"><span>Travel distance · Class A</span><b class="pill" id="check-distance">—</b></div><div class="compliance-row"><span>Electrical coverage · Class C</span><b class="pill" id="check-electrical">—</b></div><div class="compliance-row"><span>Equipment clearance</span><b class="pill" id="check-clearance">—</b></div></section><section class="sim-card"><div class="sim-head"><span class="sim-title">▣　EVACUATION DRILL</span><span class="pill" id="sim-state">READY</span></div><button class="sim-btn" id="sim-button">▶　Start simulation</button><div class="smallprint" id="sim-caption">Spawn 12 occupants and test your evacuation plan.</div></section></aside></div><footer class="footer"><span>FIREWATCH SYSTEMS　·　BUILDING SAFETY SIMULATOR</span><span>● ALL CHANGES SAVED</span></footer></main>`;
const canvas=document.querySelector<HTMLCanvasElement>('#map')!,ctx=canvas.getContext('2d')!,mapWrap=document.querySelector<HTMLElement>('.map-wrap')!;

function isWalkable(x:number,y:number){return x>=0&&y>=0&&x<COLS&&y<ROWS&&!grid[y][x].wall&&!grid[y][x].furniture&&!grid[y][x].fire&&!grid[y][x].smoke;}
function neighbors(p:Point){return [{x:p.x+1,y:p.y},{x:p.x-1,y:p.y},{x:p.x,y:p.y+1},{x:p.x,y:p.y-1}].filter(q=>isWalkable(q.x,q.y));}
function pathfind(start:Point,goal:Point):Point[]{if(!isWalkable(start.x,start.y)||!isWalkable(goal.x,goal.y))return[];const key=(p:Point)=>`${p.x},${p.y}`,open=[start],came=new Map<string,Point>(),g=new Map<string,number>([[key(start),0]]);while(open.length){open.sort((a,b)=>(g.get(key(a))!+Math.abs(a.x-goal.x)+Math.abs(a.y-goal.y))-(g.get(key(b))!+Math.abs(b.x-goal.x)+Math.abs(b.y-goal.y)));const cur=open.shift()!;if(cur.x===goal.x&&cur.y===goal.y){const out=[cur];let k=key(cur);while(came.has(k)){const p=came.get(k)!;out.unshift(p);k=key(p)}return out}for(const n of neighbors(cur)){const nk=key(n),tent=g.get(key(cur))!+1;if(tent<(g.get(nk)??Infinity)){came.set(nk,cur);g.set(nk,tent);if(!open.some(p=>key(p)===nk))open.push(n)}}}return[];}
function findNearestExit(p:Point){const goals=route.length?route.slice(-1):[exit];return goals[0];}
function audit(){const violations:{code:string;location:Point;message:string}[]=[];let walkable=0,covered=0;for(let y=0;y<ROWS;y++)for(let x=0;x<COLS;x++)if(isWalkable(x,y)){walkable++;let near=Infinity;for(const e of extinguishers.filter(e=>e.type==='A')){const path=pathfind({x,y},e);if(path.length)near=Math.min(near,path.length-1)}if(near<=45)covered++;else violations.push({code:'TRAVEL_DISTANCE_EXCEEDED',location:{x,y},message:'Class A extinguisher is more than 45 grid units away.'})}const uncoveredHazards=hazards.filter(h=>h.type==='ELECTRICAL'&&!extinguishers.filter(e=>e.type==='C').some(e=>{const p=pathfind(h,e);return p.length&&p.length-1<=30}));uncoveredHazards.forEach(h=>violations.push({code:'HAZARD_MISMATCH',location:h,message:'Electrical hazard needs Class C coverage within 15 m.'}));const blocked=extinguishers.filter(e=>[{x:e.x+1,y:e.y},{x:e.x-1,y:e.y},{x:e.x,y:e.y+1},{x:e.x,y:e.y-1}].some(p=>grid[p.y]?.[p.x]?.furniture));blocked.forEach(e=>violations.push({code:'OBSTRUCTION',location:e,message:'Move furniture away from this extinguisher.'}));const score=Math.max(0,Math.round(100*(walkable?covered/walkable:1)-uncoveredHazards.length*8-blocked.length*4));return{passed:violations.length===0,complianceScore:score,violations,travelOk:covered===walkable,electricalOk:uncoveredHazards.length===0,clearanceOk:blocked.length===0};}
let auditResult=audit(),hover:Point|null=null,tilePx=20,origin={x:0,y:0};
function resize(){const r=mapWrap.getBoundingClientRect(),dpr=Math.min(window.devicePixelRatio||1,2);canvas.width=Math.max(1,Math.floor(r.width*dpr));canvas.height=Math.max(1,Math.floor(r.height*dpr));canvas.style.width=`${r.width}px`;canvas.style.height=`${r.height}px`;ctx.setTransform(dpr,0,0,dpr,0,0);draw();}
function layout(){const w=mapWrap.clientWidth,h=mapWrap.clientHeight;tilePx=Math.min((w-32)/COLS,(h-36)/ROWS)*zoom;origin={x:(w-COLS*tilePx)/2+pan.x,y:(h-ROWS*tilePx)/2+pan.y};}
function center(p:Point){return{x:origin.x+(p.x+.5)*tilePx,y:origin.y+(p.y+.5)*tilePx}}
function draw(){if(!ctx||!canvas.width)return;const w=mapWrap.clientWidth,h=mapWrap.clientHeight;layout();ctx.clearRect(0,0,w,h);ctx.fillStyle='#141b17';ctx.fillRect(0,0,w,h);const ox=origin.x,oy=origin.y,s=tilePx;ctx.fillStyle='#202923';ctx.fillRect(ox,oy,COLS*s,ROWS*s);
// Layer 0: floor plan, walls and furniture.
for(let y=0;y<ROWS;y++)for(let x=0;x<COLS;x++){const c=grid[y][x],px=ox+x*s,py=oy+y*s;if(!c.wall){ctx.fillStyle=((x+y)%2===0)?'#202923':'#1f2722';ctx.fillRect(px,py,s,s);if(snapping){ctx.strokeStyle='#2c3730';ctx.lineWidth=.55;ctx.strokeRect(px,py,s,s)}}if(c.wall){ctx.fillStyle='#49534d';ctx.fillRect(px,py,s,s);ctx.fillStyle='#606b63';ctx.fillRect(px,py,s,Math.max(2,s*.13));ctx.fillStyle='#313a34';ctx.fillRect(px,py+s*.15,s,s*.85)}if(c.furniture){ctx.fillStyle='#465149';ctx.beginPath();ctx.roundRect(px+s*.12,py+s*.12,s*.76,s*.76,3);ctx.fill();ctx.strokeStyle='#657269';ctx.strokeRect(px+s*.2,py+s*.2,s*.6,s*.6)}if(c.fire){ctx.fillStyle=`rgba(255,91,43,${.35+c.fire*.14})`;ctx.fillRect(px,py,s,s);ctx.fillStyle='#ffae57';ctx.beginPath();ctx.arc(px+s/2,py+s/2,s*.18,0,7);ctx.fill()}else if(c.smoke){ctx.fillStyle=`rgba(180,190,183,${.13+c.smoke*.05})`;ctx.fillRect(px,py,s,s)}}
// Room names and fixed exit marker.
ctx.textAlign='center';ctx.textBaseline='middle';ctx.font=`${Math.max(8,s*.37)}px 'DM Mono', monospace`;ctx.fillStyle='#66746a';[['ASSEMBLY',5,3],['PRODUCTION',15,3],['STORAGE',24,3],['PACKING',5,12],['ELECTRICAL',15,12],['KITCHEN',24,12]].forEach(([name,x,y])=>ctx.fillText(String(name),ox+(Number(x)+2.5)*s,oy+Number(y)*s));const ex=center(exit);ctx.fillStyle='#d5fca9';ctx.fillRect(ex.x-s*.5,ex.y-s*.48,s,s*.96);ctx.fillStyle='#273325';ctx.font=`bold ${s*.31}px sans-serif`;ctx.fillText('EXIT',ex.x,ex.y);
// Layer 2: safety coverage and route vectors.
