else if(tool==='hazard'){const type:HazardType=hazards.length%3===0?'ELECTRICAL':hazards.length%3===1?'GREASE':'COMBUSTIBLE';hazards.push({id:Date.now(),type,x:p.x,y:p.y,active:true});selected=p;showToast(`${type.toLowerCase()} hazard marked`);refreshUI()}
else if(tool==='route'){if(!isWalkable(p.x,p.y)&&!(p.x===exit.x&&p.y===exit.y)){showToast('Route nodes must stay on walkable floor');return}if(!route.length){if(p.x===exit.x&&p.y===exit.y){showToast('Start inside a usable room first');return}route=[p]}else if(route.length===1&&route[0].x===exit.x&&route[0].y===exit.y){route=[p]}else{const last=route[route.length-1],segment=pathfind(last,p);if(!segment.length&&Math.abs(last.x-p.x)+Math.abs(last.y-p.y)>1){showToast('Route cannot pass through a wall');return}if(p.x===exit.x&&p.y===exit.y){route.push(p);showToast('Evacuation route connected to EXIT DOOR ✓')}else if(last.x===exit.x&&last.y===exit.y){route=[p]}else route.push(p)}selected=p;refreshUI()}
else if(tool==='erase'){const ei=extinguishers.findIndex(o=>o.x===p.x&&o.y===p.y),hi=hazards.findIndex(o=>o.x===p.x&&o.y===p.y);if(ei>=0)extinguishers.splice(ei,1);else if(hi>=0)hazards.splice(hi,1);else if(route.length>1)route.pop();selected=null;refreshUI()}
else{selected=p;const ei=extinguishers.findIndex(o=>o.x===p.x&&o.y===p.y),hi=hazards.findIndex(o=>o.x===p.x&&o.y===p.y);if(ei>=0)selected={x:extinguishers[ei].x,y:extinguishers[ei].y};else if(hi>=0)selected={x:hazards[hi].x,y:hazards[hi].y};refreshUI()}draw()});
window.addEventListener('keydown',e=>{if(e.key==='Escape'){if(tool==='route'){route=[];showToast('Route cleared — start in a room and connect to EXIT')}setTool('select');draw()}if(['v','e','h','r'].includes(e.key.toLowerCase()))setTool(({v:'select',e:'extinguisher',h:'hazard',r:'route'} as Record<string,Tool>)[e.key.toLowerCase()])});
function spray(ext:Extinguisher){let target:Point|null=null,best=Infinity;for(let y=0;y<ROWS;y++)for(let x=0;x<COLS;x++)if(grid[y][x].fire){const dist=Math.abs(x-ext.x)+Math.abs(y-ext.y);if(dist<best){best=dist;target={x,y}}}if(!target||best>8){showToast('No fire within range — keep moving to the exit');return}const c=grid[target.y][target.x];if(c.fire===3&&ext.type==='C'){c.fire=0;c.smoke=1;damage=Math.max(0,damage-1);showToast('Electrical fire suppressed with Class C ✓')}else if(c.fire===2&&ext.type==='B'){c.fire=Math.min(3,c.fire+1);showToast('Warning: water has spread the Class B fire!')}else if(c.fire===1&&ext.type==='A'){c.fire=0;c.smoke=1;showToast('Class A fire extinguished ✓')}else if(c.fire===3){for(let y=Math.max(0,target.y-1);y<=Math.min(ROWS-1,target.y+1);y++)for(let x=Math.max(0,target.x-1);x<=Math.min(COLS-1,target.x+1);x++)grid[y][x].electrified=true;showToast('Danger! Water on Class C creates electrified tiles.')}else showToast('Wrong extinguisher class — use matching equipment');draw();}
