function simulationTick(){ticks++;for(let y=1;y<ROWS-1;y++)for(let x=1;x<COLS-1;x++){const c=grid[y][x];if(c.fire){c.fire=Math.min(3,c.fire+0.008);c.smoke=Math.min(3,c.smoke+.05);damage+=.025;if(ticks%7===0){for(const n of [{x:x+1,y},{x:x-1,y},{x,y:y+1},{x,y:y-1}]){const next=grid[n.y][n.x];if(!next.wall&&!next.furniture&&!next.fire&&!next.electrified&&Math.random()<.17+c.fire*.06)next.fire=c.fire}}}else if(c.smoke>0){c.smoke=Math.max(0,c.smoke-.015);if(ticks%15===0)for(const n of [{x:x+1,y},{x:x-1,y},{x,y:y+1},{x,y:y-1}]){const next=grid[n.y][n.x];if(!next.wall&&!next.furniture)next.smoke=Math.min(2,next.smoke+.04)}}}
