function pathfind(start:Point,goal:Point):Point[]{if(!isWalkable(start.x,start.y)||!isWalkable(goal.x,goal.y))return[];const key=(p:Point)=>`${p.x},${p.y}`,open=[start],came=new Map<string,Point>(),g=new Map<string,number>([[key(start),0]]);while(open.length){open.sort((a,b)=>(g.get(key(a))!+Math.abs(a.x-goal.x)+Math.abs(a.y-goal.y))-(g.get(key(b))!+Math.abs(b.x-goal.x)+Math.abs(b.y-goal.y)));const cur=open.shift()!;if(cur.x===goal.x&&cur.y===goal.y){const out=[cur];let k=key(cur);while(came.has(k)){const p=came.get(k)!;out.unshift(p);k=key(p)}return out}for(const n of [{x:cur.x+1,y:cur.y},{x:cur.x-1,y:cur.y},{x:cur.x,y:cur.y+1},{x:cur.x,y:cur.y-1}].filter(p=>isWalkable(p.x,p.y))){const nk=key(n),tent=g.get(key(cur))!+1;if(tent<(g.get(nk)??Infinity)){came.set(nk,cur);g.set(nk,tent);if(!open.some(p=>key(p)===nk))open.push(n)}}}return[];}
