let auditResult=audit();function center(p:Point){return{x:origin.x+(p.x+.5)*tilePx,y:origin.y+(p.y+.5)*tilePx}}
function resize(){const r=mapWrap.getBoundingClientRect(),dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.max(1,Math.floor(r.width*dpr));canvas.height=Math.max(1,Math.floor(r.height*dpr));canvas.style.width=`${r.width}px`;canvas.style.height=`${r.height}px`;ctx.setTransform(dpr,0,0,dpr,0,0);draw()}
function draw(){if(!canvas.width)return;const w=mapWrap.clientWidth,h=mapWrap.clientHeight;tilePx=Math.min((w-32)/COLS,(h-36)/ROWS)*zoom;origin={x:(w-COLS*tilePx)/2+pan.x,y:(h-ROWS*tilePx)/2+pan.y};ctx.clearRect(0,0,w,h);ctx.fillStyle='#141b17';ctx.fillRect(0,0,w,h);ctx.fillStyle='#202923';ctx.fillRect(origin.x,origin.y,COLS*tilePx,ROWS*tilePx);const s=tilePx;
// Layer 0: walls and furniture.
for(let y=0;y<ROWS;y++)for(let x=0;x<COLS;x++){const c=grid[y][x],px=origin.x+x*s,py=origin.y+y*s;if(!c.wall){ctx.fillStyle=(x+y)%2?'#1f2722':'#202923';ctx.fillRect(px,py,s,s);if(snapping){ctx.strokeStyle='#2c3730';ctx.lineWidth=.55;ctx.strokeRect(px,py,s,s)}}if(c.wall){ctx.fillStyle='#49534d';ctx.fillRect(px,py,s,s);ctx.fillStyle='#606b63';ctx.fillRect(px,py,s,Math.max(2,s*.13));ctx.fillStyle='#313a34';ctx.fillRect(px,py+s*.15,s,s*.85)}if(c.furniture){ctx.fillStyle='#465149';ctx.beginPath();ctx.roundRect(px+s*.12,py+s*.12,s*.76,s*.76,3);ctx.fill();ctx.strokeStyle='#657269';ctx.strokeRect(px+s*.2,py+s*.2,s*.6,s*.6)}if(c.fire){ctx.fillStyle=`rgba(255,91,43,${.35+c.fire*.14})`;ctx.fillRect(px,py,s,s);ctx.fillStyle='#ffae57';ctx.beginPath();ctx.arc(px+s/2,py+s/2,s*.18,0,7);ctx.fill()}else if(c.smoke){ctx.fillStyle=`rgba(180,190,183,${.13+c.smoke*.05})`;ctx.fillRect(px,py,s,s)}}
ctx.textAlign='center';ctx.textBaseline='middle';ctx.font=`${Math.max(8,s*.37)}px monospace`;ctx.fillStyle='#66746a';[['ASSEMBLY',5,3],['PRODUCTION',15,3],['STORAGE',24,3],['PACKING',5,12],['ELECTRICAL',15,12],['KITCHEN',24,12]].forEach(([name,x,y])=>ctx.fillText(String(name),origin.x+(Number(x)+2.5)*s,origin.y+Number(y)*s));const ex=center(exit);ctx.fillStyle='#d5fca9';ctx.fillRect(ex.x-s*.5,ex.y-s*.48,s,s*.96);ctx.fillStyle='#273325';ctx.font=`bold ${s*.31}px sans-serif`;ctx.fillText('EXIT',ex.x,ex.y);
