for(const e of extinguishers){const p=center(e);ctx.beginPath();ctx.arc(p.x,p.y,e.radius*s,0,Math.PI*2);ctx.fillStyle=e.type==='C'?'rgba(93,187,255,.055)':'rgba(185,250,98,.045)';ctx.fill();ctx.setLineDash([5,5]);ctx.strokeStyle=e.type==='C'?'rgba(93,187,255,.2)':'rgba(185,250,98,.2)';ctx.lineWidth=1;ctx.stroke();ctx.setLineDash([])}
