function cellAt(x:number,y:number):Point|null{const a=Math.floor((x-origin.x)/tilePx),b=Math.floor((y-origin.y)/tilePx);return a>=0&&b>=0&&a<COLS&&b<ROWS?{x:a,y:b}:null}function pointerPos(e:PointerEvent){const r=canvas.getBoundingClientRect();return{x:e.clientX-r.left,y:e.clientY-r.top}}
canvas.addEventListener('pointermove',e=>{const p=pointerPos(e);if(dragging&&dragStart){pan.x+=p.x-dragStart.x;pan.y+=p.y-dragStart.y;dragStart=p;draw();return}hover=cellAt(p.x,p.y);draw()});canvas.addEventListener('pointerdown',e=>{if(e.button===1||e.button===2){dragging=true;dragStart=pointerPos(e);canvas.setPointerCapture(e.pointerId);e.preventDefault()}});canvas.addEventListener('pointerup',()=>{dragging=false;dragStart=null});canvas.addEventListener('contextmenu',e=>e.preventDefault());canvas.addEventListener('wheel',e=>{e.preventDefault();zoom=Math.max(.55,Math.min(2.4,zoom*(e.deltaY<0?1.09:.92)));document.querySelector('#zoom-label')!.textContent=`${Math.round(zoom*100)}%`;draw()},{passive:false});
